document.body.insertAdjacentHTML('beforeend',`<dialog id="flipbookDialog"><div class="tool-heading"><div><div class="eyebrow">ONE DRAWING AT A TIME</div><h2>Frame-by-frame animation</h2></div><button id="closeFlipbook">Cancel</button></div><div class="flipbook-tools"><label>Name<input id="flipbookName" maxlength="80" value="My drawing animation"></label><label>FPS<select id="flipbookFPS"><option>6</option><option>8</option><option selected>12</option><option>15</option><option>24</option><option>30</option></select></label><label class="toggle-tool"><input id="flipbookLoop" type="checkbox" checked> Loop</label><button id="playFlipbook">▶ Play</button></div><div class="flipbook-tools"><label>Tool<select id="flipbookTool"><option value="pen">Brush</option><option value="line">Line</option><option value="rect">Rectangle</option><option value="ellipse">Ellipse</option></select></label><label>Ink<input id="flipbookColor" type="color" value="#31564d"></label><label>Size<input id="flipbookSize" type="range" min="1" max="60" value="8"></label><label class="toggle-tool"><input id="flipbookEraser" type="checkbox"> Eraser</label><label class="toggle-tool"><input id="flipbookOnion" type="checkbox" checked> Onion skins</label><button id="undoFlipStroke">Undo stroke</button><button id="clearFlipFrame">Clear frame</button></div><div class="flipbook-paper"><canvas id="flipbookCanvas" width="800" height="450" aria-label="Frame drawing canvas"></canvas></div><div class="flipbook-tools"><button id="previousFlipFrame">← Previous</button><button id="nextFlipFrame">Next →</button><button id="blankFlipFrame">＋ Blank frame</button><button id="duplicateFlipFrame">Duplicate frame</button><button id="deleteFlipFrame">Delete frame</button><label>Hold (frames)<input id="flipbookHold" type="number" min="1" max="120" value="1"></label></div><div id="flipbookFrames" class="flipbook-frames"></div><div class="flipbook-tools"><button id="moveFlipEarlier">Move earlier</button><button id="moveFlipLater">Move later</button><label class="button">Import image frames<input id="flipbookFiles" type="file" accept="image/png,image/jpeg,image/webp" multiple hidden></label><span id="flipbookDuration" class="note"></span><button id="saveFlipbook" class="primary">Save animation</button></div><p class="note">Duplicate a frame to draw the next pose. Arrows change frames · Space plays · Ctrl+D duplicates · Ctrl+Z undoes a stroke · B brush / E eraser. Onion skins are guides and stay out of your saved frames.</p></dialog>`);
const flipCanvas=$('flipbookCanvas'),flipContext=flipCanvas.getContext('2d'),flipScratch=document.createElement('canvas'),flipGhost=document.createElement('canvas');
function blankDrawingFrame(){return{id:uid(),hold:1,strokes:[],src:''}}
function totalFlipTicks(o){return o.frames.reduce((sum,f)=>sum+f.hold,0)}
function flipFrameAt(o,t){let tick=Math.floor(Math.max(0,t-clipStart(o))*o.fps+1e-6),total=totalFlipTicks(o);tick=o.loop?tick%total:Math.min(total-1,tick);for(let i=0;i<o.frames.length;i++){if(tick<o.frames[i].hold)return i;tick-=o.frames[i].hold}return o.frames.length-1}
function drawFrameArtwork(c,frame,w,h){c.clearRect(0,0,w,h);if(frame.baseSrc){const image=loadImage(frame.baseSrc);if(image.complete&&image.naturalWidth)c.drawImage(image,0,0,w,h)}c.lineCap='round';c.lineJoin='round';for(const stroke of frame.strokes){const a=stroke.points[0],b=stroke.points.at(-1);c.globalCompositeOperation=stroke.erase?'destination-out':'source-over';c.strokeStyle=stroke.color;c.fillStyle=stroke.color;c.lineWidth=stroke.size;c.beginPath();if(stroke.tool==='rect')c.rect(Math.min(a.x,b.x),Math.min(a.y,b.y),Math.abs(b.x-a.x),Math.abs(b.y-a.y));else if(stroke.tool==='ellipse')c.ellipse((a.x+b.x)/2,(a.y+b.y)/2,Math.max(.1,Math.abs(a.x-b.x)/2),Math.max(.1,Math.abs(a.y-b.y)/2),0,0,Math.PI*2);else{c.moveTo(a.x,a.y);for(const p of stroke.tool==='line'?[b]:stroke.points.slice(1))c.lineTo(p.x,p.y)}if(stroke.points.length===1){c.arc(a.x,a.y,stroke.size/2,0,Math.PI*2);c.fill()}else c.stroke()}c.globalCompositeOperation='source-over'}
function bakeFlipFrame(index=flipIndex){const frame=flipDraft.frames[index];flipScratch.width=flipDraft.frameWidth;flipScratch.height=flipDraft.frameHeight;drawFrameArtwork(flipScratch.getContext('2d'),frame,flipScratch.width,flipScratch.height);frame.src=flipScratch.toDataURL('image/png');return frame.src}
function paintFlipbook(){if(!flipDraft)return;const w=flipDraft.frameWidth,h=flipDraft.frameHeight;flipContext.clearRect(0,0,w,h);if($('flipbookOnion').checked&&!flipPlaying)for(const[index,color]of[[flipIndex-1,'#58b2dd'],[flipIndex+1,'#df9c52']]){const frame=flipDraft.frames[index];if(!frame?.src)continue;const image=loadImage(frame.src);if(!image.complete)continue;flipGhost.width=w;flipGhost.height=h;const g=flipGhost.getContext('2d');g.drawImage(image,0,0,w,h);g.globalCompositeOperation='source-in';g.fillStyle=color;g.fillRect(0,0,w,h);flipContext.save();flipContext.globalAlpha=.22;flipContext.drawImage(flipGhost,0,0);flipContext.restore()}flipScratch.width=w;flipScratch.height=h;drawFrameArtwork(flipScratch.getContext('2d'),flipDraft.frames[flipIndex],w,h);flipContext.drawImage(flipScratch,0,0)}
function renderFlipbookFrames(){const row=$('flipbookFrames');row.replaceChildren();flipDraft.frames.forEach((frame,i)=>{const button=document.createElement('button');button.className='flipbook-frame'+(i===flipIndex?' active':'');button.dataset.frame=i;const image=document.createElement('img');image.src=frame.src;image.alt='Frame '+(i+1);const label=document.createElement('span');label.textContent=(i+1)+' · '+frame.hold+'f';button.append(image,label);button.onclick=()=>{stopFlipPlayback();flipIndex=i;renderFlipbookFrames();paintFlipbook()};row.append(button)});$('flipbookHold').value=flipDraft.frames[flipIndex].hold;$('flipbookDuration').textContent=flipDraft.frames.length+' drawings · '+(totalFlipTicks(flipDraft)/flipDraft.fps).toFixed(2)+' seconds';$('deleteFlipFrame').disabled=flipDraft.frames.length<2;$('previousFlipFrame').disabled=flipIndex===0;$('nextFlipFrame').disabled=flipIndex===flipDraft.frames.length-1}
function stopFlipPlayback(){flipPlaying=false;cancelAnimationFrame(flipRAF);$('playFlipbook').textContent='▶ Play'}
function openFlipbook(o=null){stop();flipEditId=o?.id||null;if(o?.locked)return toast('Unlock this drawing animation before editing frames.');if(o)flipDraft=structuredClone(o);else{const format=project.canvasFormat||'landscape',w=format==='portrait'?360:format==='square'?640:800,h=format==='portrait'?640:format==='square'?640:450;flipDraft={name:'My drawing animation',fps:12,loop:true,frameWidth:w,frameHeight:h,frames:[blankDrawingFrame()]}}flipIndex=0;stopFlipPlayback();flipCanvas.width=flipDraft.frameWidth;flipCanvas.height=flipDraft.frameHeight;flipCanvas.style.aspectRatio=flipDraft.frameWidth+'/'+flipDraft.frameHeight;$('flipbookName').value=flipDraft.name;$('flipbookFPS').value=flipDraft.fps;$('flipbookLoop').checked=flipDraft.loop;for(let i=0;i<flipDraft.frames.length;i++)if(!flipDraft.frames[i].src)bakeFlipFrame(i);renderFlipbookFrames();paintFlipbook();$('flipbookDialog').showModal()}
$('drawAnimation').onclick=$('newFlipbook').onclick=()=>openFlipbook();$('closeFlipbook').onclick=()=>$('flipbookDialog').close();$('flipbookDialog').addEventListener('close',()=>{stopFlipPlayback();flipStroke=null});
function addFlipFrame(duplicate){if(flipDraft.frames.length>=120)return toast('Keep up to 120 drawings per animation.');stopFlipPlayback();const frame=duplicate?structuredClone(flipDraft.frames[flipIndex]):blankDrawingFrame();frame.id=uid();flipDraft.frames.splice(++flipIndex,0,frame);bakeFlipFrame();renderFlipbookFrames();paintFlipbook()}
$('blankFlipFrame').onclick=()=>addFlipFrame(false);$('duplicateFlipFrame').onclick=()=>addFlipFrame(true);$('deleteFlipFrame').onclick=()=>{if(flipDraft.frames.length<2)return;stopFlipPlayback();flipDraft.frames.splice(flipIndex,1);flipIndex=Math.min(flipIndex,flipDraft.frames.length-1);renderFlipbookFrames();paintFlipbook()};
for(const[id,delta]of[['previousFlipFrame',-1],['nextFlipFrame',1]])$(id).onclick=()=>{stopFlipPlayback();flipIndex=clamp(flipIndex+delta,0,flipDraft.frames.length-1);renderFlipbookFrames();paintFlipbook()};
for(const[id,delta]of[['moveFlipEarlier',-1],['moveFlipLater',1]])$(id).onclick=()=>{const to=flipIndex+delta;if(to<0||to>=flipDraft.frames.length)return;stopFlipPlayback();[flipDraft.frames[flipIndex],flipDraft.frames[to]]=[flipDraft.frames[to],flipDraft.frames[flipIndex]];flipIndex=to;renderFlipbookFrames();paintFlipbook()};
$('undoFlipStroke').onclick=()=>{stopFlipPlayback();flipDraft.frames[flipIndex].strokes.pop();bakeFlipFrame();renderFlipbookFrames();paintFlipbook()};$('clearFlipFrame').onclick=()=>{stopFlipPlayback();flipDraft.frames[flipIndex].strokes=[];delete flipDraft.frames[flipIndex].baseSrc;bakeFlipFrame();renderFlipbookFrames();paintFlipbook()};$('flipbookOnion').onchange=paintFlipbook;$('flipbookFPS').onchange=e=>{flipDraft.fps=+e.target.value;renderFlipbookFrames()};$('flipbookHold').onchange=e=>{flipDraft.frames[flipIndex].hold=Math.round(clamp(+e.target.value||1,1,120));renderFlipbookFrames()};
$('playFlipbook').onclick=()=>{if(flipPlaying){stopFlipPlayback();renderFlipbookFrames();paintFlipbook();return}flipPlaying=true;$('playFlipbook').textContent='Ⅱ Pause';const start=performance.now();function tick(now){if(!flipPlaying)return;flipIndex=flipFrameAt({...flipDraft,in:0,loop:$('flipbookLoop').checked},(now-start)/1000);paintFlipbook();if((now-start)/1000<totalFlipTicks(flipDraft)/flipDraft.fps||$('flipbookLoop').checked)flipRAF=requestAnimationFrame(tick);else{stopFlipPlayback();renderFlipbookFrames()}}flipRAF=requestAnimationFrame(tick)};
function flipPoint(e){const r=flipCanvas.getBoundingClientRect();return{x:clamp((e.clientX-r.left)*flipCanvas.width/r.width,0,flipCanvas.width),y:clamp((e.clientY-r.top)*flipCanvas.height/r.height,0,flipCanvas.height)}}
flipCanvas.onpointerdown=e=>{if(e.button!==0)return;stopFlipPlayback();const frame=flipDraft.frames[flipIndex];if(frame.strokes.length>=500)return toast('This frame has many strokes. Start another drawing frame.');flipStroke={tool:$('flipbookTool').value,color:$('flipbookColor').value,size:+$('flipbookSize').value,erase:$('flipbookEraser').checked,points:[flipPoint(e)]};frame.strokes.push(flipStroke);flipCanvas.setPointerCapture(e.pointerId);paintFlipbook()};flipCanvas.onpointermove=e=>{if(!flipStroke)return;if(flipStroke.points.length<10000)flipStroke.points.push(flipPoint(e));paintFlipbook()};flipCanvas.onpointerup=()=>{if(!flipStroke)return;flipStroke=null;bakeFlipFrame();renderFlipbookFrames();paintFlipbook()};flipCanvas.onpointercancel=()=>{if(flipStroke)flipDraft.frames[flipIndex].strokes.pop();flipStroke=null;paintFlipbook()};
$('flipbookFiles').onchange=async e=>{const files=Array.from(e.target.files);e.target.value='';stopFlipPlayback();for(const file of files){if(flipDraft.frames.length>=120)break;if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>8e6)continue;try{const source=await imageReady(await dataURL(file)),canvas=document.createElement('canvas');canvas.width=flipDraft.frameWidth;canvas.height=flipDraft.frameHeight;const c=canvas.getContext('2d'),scale=Math.min(canvas.width/source.naturalWidth,canvas.height/source.naturalHeight);c.drawImage(source,(canvas.width-source.naturalWidth*scale)/2,(canvas.height-source.naturalHeight*scale)/2,source.naturalWidth*scale,source.naturalHeight*scale);const src=canvas.toDataURL('image/png'),frame={id:uid(),hold:1,strokes:[],baseSrc:src,src};flipDraft.frames.splice(++flipIndex,0,frame);await imageReady(src)}catch{toast('Could not import '+file.name)}}renderFlipbookFrames();paintFlipbook()};
$('saveFlipbook').onclick=()=>{stopFlipPlayback();flipDraft.name=$('flipbookName').value.trim()||'Drawing animation';flipDraft.fps=+$('flipbookFPS').value;flipDraft.loop=$('flipbookLoop').checked;const duration=totalFlipTicks(flipDraft)/flipDraft.fps;if(duration>60)return toast('Keep this animation to 60 seconds or less.');if(!flipDraft.frames.some(f=>f.strokes.some(s=>!s.erase)||f.baseSrc))return toast('Draw or import at least one frame.');let o=current().objects.find(o=>o.id===flipEditId);if(o?.locked)return toast('Unlock this layer before saving frames.');const data={name:flipDraft.name,fps:flipDraft.fps,loop:flipDraft.loop,frameWidth:flipDraft.frameWidth,frameHeight:flipDraft.frameHeight,frames:structuredClone(flipDraft.frames)};if(o)Object.assign(o,data);else{const view=projectView(),width=Math.min(view.width*.7,view.height*.7*data.frameWidth/data.frameHeight),start=clamp(time,0,current().duration-.1);if(!data.loop&&start+duration>current().duration&&start+duration<=60)changeSceneDuration(current(),start+duration);o={id:uid(),type:'flipbook',ease:'smooth',...data,width,height:width*data.frameHeight/data.frameWidth,in:start,out:data.loop?current().duration:Math.min(current().duration,start+duration),keys:[{t:start,v:{...pose,x:480,y:270}}]};current().objects.push(o)}selected=o.id;save();render();$('flipbookDialog').close();toast('Drawing animation added. Move and animate it like any other layer.')};
document.addEventListener('keydown',e=>{if(!$('flipbookDialog').open||e.target.matches('input,textarea,select'))return;if(e.code==='Space'){e.preventDefault();$('playFlipbook').click()}else if(e.key==='ArrowLeft'||e.key==='ArrowRight'){e.preventDefault();$(e.key==='ArrowLeft'?'previousFlipFrame':'nextFlipFrame').click()}else if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='d'){e.preventDefault();addFlipFrame(true)}else if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'){e.preventDefault();$('undoFlipStroke').click()}else if(e.key.toLowerCase()==='b')$('flipbookEraser').checked=false;else if(e.key.toLowerCase()==='e')$('flipbookEraser').checked=true});
const propBeforeFlipbook=prop;prop=function(c,o,v){if(o.type!=='flipbook')return propBeforeFlipbook(c,o,v);const frame=o.frames[flipFrameAt(o,time)],image=loadImage(frame.src);if(!image.complete||!image.naturalWidth)return;c.save();c.translate(v.x,v.y);c.rotate(v.rotation*Math.PI/180);c.scale(v.scale,v.scale);c.globalAlpha=v.opacity;c.drawImage(image,-o.width/2,-o.height/2,o.width,o.height);c.restore()};
const boundsBeforeFlipbook=bounds;bounds=function(o,v){return o.type==='flipbook'?{x:v.x-o.width*v.scale/2,y:v.y-o.height*v.scale/2,w:o.width*v.scale,h:o.height*v.scale}:boundsBeforeFlipbook(o,v)};
const flipControls=renderControls;renderControls=function(){flipControls();const o=object();if(o?.type!=='flipbook')return;const panel=document.createElement('details');panel.open=true;panel.innerHTML='<summary>Drawing animation</summary><p class="note">'+o.frames.length+' drawings · '+o.fps+' fps · '+(totalFlipTicks(o)/o.fps).toFixed(2)+'s</p><button id="editFlipbook">Edit drawing frames</button><label class="toggle-tool"><input id="layerFlipLoop" type="checkbox"> Loop within clip</label>';$('controls').prepend(panel);$('layerFlipLoop').checked=o.loop;$('layerFlipLoop').onchange=e=>{if(o.locked)return;o.loop=e.target.checked;save();draw()};$('editFlipbook').onclick=()=>openFlipbook(o);panel.querySelectorAll('button,input').forEach(e=>e.disabled=!!o.locked)};
const exportBeforeFlipbooks=$('renderVideo').onclick;$('renderVideo').onclick=async()=>{await Promise.all(project.scenes.flatMap(s=>s.objects.filter(o=>o.type==='flipbook').flatMap(o=>o.frames.map(f=>imageReady(f.src)))));return exportBeforeFlipbooks()};
const thumbBeforeFlipbooks=renderStoryThumbnail;renderStoryThumbnail=async function(canvas,s){await Promise.all(s.objects.filter(o=>o.type==='flipbook').flatMap(o=>o.frames.map(f=>imageReady(f.src))));return thumbBeforeFlipbooks(canvas,s)};
const flipValidator=valid;valid=function(p){return flipValidator(p)&&p.scenes.every(s=>s.objects.every(o=>o.type!=='flipbook'||Number.isInteger(o.fps)&&o.fps>=1&&o.fps<=30&&typeof o.loop==='boolean'&&Number.isFinite(o.width)&&o.width>0&&o.width<=1600&&Number.isFinite(o.height)&&o.height>0&&o.height<=1600&&Number.isInteger(o.frameWidth)&&o.frameWidth>=1&&o.frameWidth<=1000&&Number.isInteger(o.frameHeight)&&o.frameHeight>=1&&o.frameHeight<=1000&&Array.isArray(o.frames)&&o.frames.length>0&&o.frames.length<=120&&totalFlipTicks(o)/o.fps<=60&&o.frames.every(f=>Number.isInteger(f.hold)&&f.hold>=1&&f.hold<=120&&typeof f.src==='string'&&f.src.length<12e6&&f.src.startsWith('data:image/png;base64,')&&(!f.baseSrc||typeof f.baseSrc==='string'&&f.baseSrc.length<12e6&&f.baseSrc.startsWith('data:image/png;base64,'))&&Array.isArray(f.strokes)&&f.strokes.length<=500&&f.strokes.every(stroke=>['pen','line','rect','ellipse'].includes(stroke.tool)&&/^#[0-9a-f]{6}$/i.test(stroke.color)&&Number.isFinite(stroke.size)&&stroke.size>=1&&stroke.size<=60&&typeof stroke.erase==='boolean'&&Array.isArray(stroke.points)&&stroke.points.length>0&&stroke.points.length<=10000&&stroke.points.every(pt=>Number.isFinite(pt.x)&&Number.isFinite(pt.y)&&pt.x>=0&&pt.x<=o.frameWidth&&pt.y>=0&&pt.y<=o.frameHeight)))))};
